1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export interface QuoteStep {
7	  op: "quote";
8	  items: {
9	    type: KnownItemType;
10	    material?: string;
11	    enchantment?: number;
12	    cursed?: boolean;
13	  }[];
14	}
15	
16	export type Step = QuoteStep;
17	
18	export interface ScenarioResults {
19	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
20	}
21	
22	const PROCESSING_FEE = 5;
23	const BASE_PREMIUM_BY_TYPE = {
24	  sword: 100,
25	  amulet: 60,
26	  staff: 80,
27	  potion: 40,
28	  rune: 25,
29	} as const satisfies Record<string, number>;
30	
31	export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
32	const FIRST_INSURANCE_SURCHARGE = 0.1;
33	
34	// Percentage arithmetic leaves values like 71.00000000000001, which would
35	// otherwise round up to 72. Settle the float noise before rounding.
36	const FLOAT_NOISE_DIGITS = 6;
37	const withoutFloatNoise = (amount: number): number =>
38	  Number(amount.toFixed(FLOAT_NOISE_DIGITS));
39	
40	const roundUpInFavourOfMHPCO = (amount: number): number =>
41	  Math.ceil(withoutFloatNoise(amount));
42	
43	type Item = QuoteStep["items"][number];
44	
45	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
46	
47	const increasedBy = (amount: number, rate: number): number =>
48	  amount * (1 + rate);
49	
50	const BLOCK_SIZE = 3;
51	const BLOCK_BASE_PREMIUM = 60;
52	
53	const allAlike = (items: Item[]): boolean =>
54	  items.every((item) => item.type === items[0].type);
55	
56	// Known-incomplete: recognises a block only when the whole policy IS one
57	// block. Policies that merely CONTAIN a block (4 runes, 3 runes + 3
58	// moonstones) are not handled yet — the pending tests will force the split.
59	const isExactlyOneBlock = (items: Item[]): boolean =>
60	  items.length === BLOCK_SIZE && allAlike(items);
61	
62	const sumOfBasePremiums = (items: Item[]): number =>
63	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
64	
65	const policyBasePremiumOf = (items: Item[]): number =>
66	  isExactlyOneBlock(items) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(items);
67	
68	const quotePremium = (step: QuoteStep): number =>
69	  roundUpInFavourOfMHPCO(
70	    increasedBy(policyBasePremiumOf(step.items), FIRST_INSURANCE_SURCHARGE) +
71	      PROCESSING_FEE,
72	  );
73	
74	export const runScenario = (scenario: Scenario): ScenarioResults => ({
75	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
76	});
